INSERT INTO `boss_info` VALUES (1,'牲鬼·布林格',953,70,'/boss_image/1.png','冰','物理',44919296,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshb3ktc-do1pjk\", \"name\": \"场地 Buff\", \"note\": \"对首领敌人施加属性异常或[紊乱]效果时，全队获得1层[心无旁骛]，最多叠加6层，每层[心无旁骛]会使代理人的暴击率提升5%；拥有至少3层[心无旁骛]后，队伍中任意代理人对敌人施加属性异常效果时，该效果的持续时间提升5秒；牲鬼·布林格召唤「牲祭之刃」发动攻击时，全队[心无旁骛]层数将会被重置。\", \"effects\": [{\"id\": \"eff-mshb3ktc-uu72cu\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"critRate\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 6, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 6, \"elementFilter\": \"all\", \"valuePerStack\": 5, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"skillSubcategoryId\": null}, {\"id\": \"eff-mshb4d53-rbjb1x\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"anomalyDuration\", \"scope\": \"general\", \"value\": 5, \"origin\": \"\", \"maxStacks\": 1, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 1, \"elementFilter\": \"all\", \"valuePerStack\": 0, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(2,'霸主侵蚀体·庞培',953,70,'/boss_image/2.png','火','电',44919296,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshb4zf4-6ksoch\", \"name\": \"场地 Buff\", \"note\": \"首领敌人每10秒获得1层[愈战愈勇]，使自身造成伤害提升20%，最多叠加3层；队伍中任意代理人对敌人施加属性异常效果时，将移除1层[愈战愈勇]并削弱目标，使其受到伤害提升15%，持续20秒。\", \"effects\": [{\"id\": \"eff-mshb4zf4-v0p2dm\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"vulnerable\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 3, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 3, \"elementFilter\": \"all\", \"valuePerStack\": 15, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(3,'恶名·冥宁芙',953,70,'/boss_image/3.png','冰 以太','无',58049652,2.000,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshao9gt-rcx0g4\", \"name\": \"场地 Buff\", \"note\": \"首领敌人造成伤害提升25%；\\n分身被击破/本体进入失衡状态时，将对首领敌人施加1层/5层[如履薄冰]， 每层[如履薄冰]会使首领敌人造成的伤害降低5%，并使代理人对其造成的冰属性伤害和以太属性伤害提升10%；\\n敌人从失衡状态恢复时，[如履薄冰]层数将会被重置。\", \"effects\": [{\"id\": \"eff-mshao9gt-oo03fu\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"dmgBonus\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 10, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 5, \"elementFilter\": [\"以太\", \"冰\"], \"valuePerStack\": 10, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(4,'自律强袭单位·提丰·破坏者型',953,70,'/boss_image/4.png','电 风','火',51208171,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshb61lm-3eu5st\", \"name\": \"场地 Buff\", \"note\": \"代理人发动[招架支援]命中首领敌人时，将对其施加1层[难敌四手]，[招架支援]累计命中3次时，将触发部位破坏，并额外施加3层[难敌四手]，每层[难敌四手]会使代理人对首领敌人造成的失衡值提升15%，在失衡状态下[连携技]和[终结技]对其造成的伤害提升10%；敌人充电蓄能时，将修复受损部位并重置部位破坏进度；敌人从失衡状态恢复时，[难敌四手]层数将会被重置。\", \"effects\": [{\"id\": \"eff-mshb61lm-7mqlnb\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"skillDmgBonus\", \"scope\": \"skill\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 9, \"stackable\": false, \"applyTarget\": \"team\", \"skillTargets\": [{\"category\": \"chain\", \"subcategoryId\": null}, {\"category\": \"ultimate\", \"subcategoryId\": null}], \"defaultStacks\": 6, \"elementFilter\": \"all\", \"skillCategory\": \"chain\", \"valuePerStack\": 10, \"applySituation\": \"stagger\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(5,'初生·死路屠夫',953,70,'/boss_image/5.png','冰 以太','无',37312835,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshb861v-t5bpbc\", \"name\": \"场地 Buff\", \"note\": \"未处于失衡状态下时，首领敌人每6秒获得1层[孤注一掷]，最多叠加3层，每层[孤注一掷]会使首领敌人造成的伤害提升10%；代理人攻击命中敌人时，目标每拥有1层[孤注一掷]，代理人的暴击伤害提升25%；敌人从失衡状态恢复时，[孤注一掷]层数将会被重置。\", \"effects\": [{\"id\": \"eff-mshb861v-m5d7qu\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"critDmg\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 3, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 3, \"elementFilter\": \"all\", \"valuePerStack\": 25, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(6,'恶名·死路屠夫',953,70,'/boss_image/6.png','冰 以太','无',44776269,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-msh9zad4-6bgcx0\", \"name\": \"场地 Buff\", \"note\": \"属性异常对首领敌人造成的伤害提升50%；恶名·死路屠夫处于[以太强化]状态时，承受的伤害降低15%，代理人对其造成的失衡值降低30%；代理人对恶名·死路屠夫触发[紊乱]后，使其立即退出[以太强化]状态。\", \"effects\": [{\"id\": \"eff-msh9zad4-87qx0z\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"anomalyDmgBonus\", \"scope\": \"general\", \"value\": 50, \"origin\": \"\", \"maxStacks\": 1, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 1, \"elementFilter\": \"all\", \"valuePerStack\": 0, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}, {\"id\": \"eff-msha0ioz-toe90f\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"vulnerable\", \"scope\": \"general\", \"value\": -15, \"origin\": \"\", \"maxStacks\": 1, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 1, \"elementFilter\": \"all\", \"valuePerStack\": 0, \"applySituation\": \"global\", \"enabledDefault\": false, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(7,'未知复合侵蚀体',953,70,'/boss_image/7.png','电 以太','无',48505819,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-msha9hqd-kdvpmp\", \"name\": \"场地 Buff\", \"note\": \"对首领敌人的腿部造成足够的伤害时，会触发[部位破坏]，代理人成功破坏首领敌人的腿部时，回复1000点喧响值，首领敌人获得1层[崩解]，持续20秒，最多4层；代理人攻击命中敌人时，目标每拥有1层[崩解]，暴击伤害提升25%。\", \"effects\": [{\"id\": \"eff-msha9hqd-urcox7\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"critDmg\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 4, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 4, \"elementFilter\": \"all\", \"valuePerStack\": 25, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(8,'恶名·庞培',953,70,'/boss_image/8.png','火','电',44919296,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshafbwe-73044k\", \"name\": \"场地 Buff\", \"note\": \"·代理人发动[招架支援]或[连携技]命中首领敌人时，将对其施加1层[劣势]，持续20秒，每层效果单独结算持续时间。代理人攻击命中敌人时，目标每拥有1层[劣势]，代理人的暴击伤害提升15%；\\n·首领敌人拥有4层[劣势]时，[招架支援]会弹开首领敌人的攻击，造成硬直效果。\\n·首领敌人受到的属性异常伤害降低30%。\", \"effects\": [{\"id\": \"eff-mshafbwe-w5yihe\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"critDmg\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 4, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 4, \"elementFilter\": \"all\", \"valuePerStack\": 15, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"skillSubcategoryId\": null}, {\"id\": \"eff-mshaga9w-lnk4dr\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"anomalyDmgBonus\", \"scope\": \"general\", \"value\": -30, \"origin\": \"\", \"maxStacks\": 1, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 1, \"elementFilter\": \"all\", \"valuePerStack\": 0, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(9,'秽息司祭',953,70,'/boss_image/9.jpg','以太','冰',91370720,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshb2hjs-qc519s\", \"name\": \"场地 Buff\", \"note\": \"秽息司祭每次切换阶段时，会使自身异常积蓄抗性提升10%，同时使自身受到的暴击伤害提高30%，至多可以叠加2层，[秽盾]被打破时，清除所有层数。\", \"effects\": [{\"id\": \"eff-mshb2hjs-9ckjaw\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"critDmg\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 2, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 2, \"elementFilter\": \"all\", \"valuePerStack\": 30, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(10,'秽息妖鬼·名可名',953,70,'/boss_image/10.png','以太 物理','火',65677784,1.250,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshah23t-9200p1\", \"name\": \"场地 Buff\", \"note\": \"秽息妖鬼每次进入属性异常时，代理人对其造成的异常伤害增加8%，最多叠加6层；开启[秽盾]时清空所有层数，每层使[秽盾]被削减效率提升2.5%。\", \"effects\": [{\"id\": \"eff-mshah23t-8vmzvz\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"anomalyDmgBonus\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 6, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 6, \"elementFilter\": \"all\", \"valuePerStack\": 8, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(11,'亵渎者',953,70,'/boss_image/11.png','电 物理','冰',70729255,1.250,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshaqd5a-kxwe5x\", \"name\": \"场地 Buff\", \"note\": \"· 代理人发动招架支援命中亵渎者时，全队获得1层[裁夺]；代理人将在空中发动攻击的亵渎者击落时，全队获得4层[裁夺]。[裁夺]最多叠加6层，持续30秒，重复触发时刷新持续时间。\\n· 每拥有1层[裁夺]，代理人的暴击伤害提升5%，物理伤害提升5%，电属性伤害提升5%。\\n· 亵渎者受到的属性异常伤害降低25%。\", \"effects\": [{\"id\": \"eff-mshaqd5a-fn61hz\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"critDmg\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 6, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 6, \"elementFilter\": \"all\", \"valuePerStack\": 5, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"skillSubcategoryId\": null}, {\"id\": \"eff-mshar0gy-nfcpxx\", \"kind\": \"stacked\", \"note\": \"\", \"stat\": \"dmgBonus\", \"scope\": \"general\", \"value\": 0, \"origin\": \"\", \"maxStacks\": 6, \"stackable\": false, \"applyTarget\":