uation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}, {\"id\": \"eff-msh5gf1y-yakx7p\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"mastery\", \"scope\": \"general\", \"value\": 60, \"origin\": \"\", \"maxStacks\": 1, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 1, \"elementFilter\": \"all\", \"valuePerStack\": 0, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}], \"enabledDefault\": true}]'),(137,'异构·基塔布鲁',953,70,'/boss_image/3114.png',NULL,NULL,162588650,1.500,'场地 Buff',NULL,NULL,'[{\"id\": \"blk-mshaaxcs-iug3ti\", \"name\": \"场地 Buff\", \"note\": \"代理人攻击命中首领敌人时，使首领敌人获得1点【紊相值】；同一名代理人每1秒最多施加1点【紊相值】。\\n首领敌人持有的【紊相值】达到10点时，会立即移除所有【紊相值】并使首领敌人进入【紊相】状态。【紊相】状态期间，敌人受到的属性异常伤害提升40%，持续秒，重复进入【紊相】状态时刷新持续时间。\\n代理人成功对首领敌人施加属性异常状态时，全队代理人会获得【升变】效果：造成的伤害提升15%，异常精通提升20点；【升变】效果持续10秒，重复触发刷新持续时间。\", \"effects\": [{\"id\": \"eff-mshaaxcs-l1ksxq\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"anomalyDmgBonus\", \"scope\": \"general\", \"value\": 40, \"origin\": \"\", \"maxStacks\": 1, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 1, \"elementFilter\": \"all\", \"valuePerStack\": 0, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}, {\"id\": \"eff-mshabuma-1fn7p3\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"dmgBonus\", \"scope\": \"general\", \"value\": 15, \"origin\": \"\", \"maxStacks\": 1, \"stackable\": false, \"applyTarget\": \"team\", \"defaultStacks\": 1, \"elementFilter\": \"all\", \"valuePerStack\": 0, \"applySituation\": \"global\", \"enabledDefault\": true, \"applyProfession\": null, \"appliesToAnomaly\": true, \"skillSubcategoryId\": null}, {\"id\": \"eff-mshac3x4-u6u4kn\", \"kind\": \"fixed\", \"note\": \"\", \"stat\": \"mastery\", \"scope\": \"general\",